import csv
import json

client_accounts = set()
with open('csv/disp.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['client_id'] == '3356':
            client_accounts.add(row['account_id'])

withdrawals = []
with open('csv/trans.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['account_id'] in client_accounts:
            if row['type'] == 'VYDAJ':
                withdrawals.append([row['trans_id'], row['account_id'], row['date'], row['type'], row['operation'], row['amount'], row['balance']])

result = {'columns': ['trans_id', 'account_id', 'date', 'type', 'operation', 'amount', 'balance'], 'rows': withdrawals}
print(json.dumps(result))

